mapper.select:
SELECT id, ad_account_asset_id, user_id, user_name, usage_team_name, is_primary, assignment_status, assignment_source, application_id, assigned_at, released_at, created_by, updated_by, created_at, updated_at FROM ad_account_asset_assignment WHERE deleted_at = 0 AND assignment_status = 'ACTIVE' AND ad_account_asset_id IN
#{assetId}
ORDER BY is_primary DESC, assigned_at ASC, id ASC

mapper.update:
UPDATE ad_account_asset_assignment
SET assignment_status = 'RELEASED',
    released_at = CURRENT_TIMESTAMP(3),
    updated_by = #{updatedBy},
    updated_at = CURRENT_TIMESTAMP(3),
    deleted_at = #{deletedAt}
WHERE ad_account_asset_id = #{assetId}
  AND user_id = #{userId}
  AND assignment_status = 'ACTIVE'
  AND deleted_at = 0
